#include "rinkfit/joint_dense_packet_document_v1.hpp"
#include "rinkfit/joint_effective_input_v1.hpp"
#include <iostream>
int main(int argc,char**argv){try{using namespace rinkfit;using J=eventio::Json;const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);std::map<std::string,std::string>allowed;auto write=[&](const std::string&name,const J&v){const auto p=out/name;eventio::atomic_json(p,v);const auto sha=eventio::file_sha256(p);allowed[p.u8string()]=sha;return J{{"file",p.u8string()},{"sha256",sha}};};
 auto parent=write("parent.json",{{"schema","rinkfit.joint_packet.v1"},{"row_count",2},{"groups",J::array({{{"id","g0"}}})},{"queries",J::array()},{"native_material_identity_revision",{{"file","old"},{"sha256",std::string(64,'a')}}}});auto authorize=[&](const auto&p){const auto key=std::filesystem::absolute(p).lexically_normal().u8string();if(!allowed.count(key))throw std::runtime_error("unauthorized generation");eventio::verify(p,allowed.at(key));};auto read=[](const auto&p){return JointEffectiveInputV1::strict_json(p);};const auto doc=read(parent.at("file").get<std::string>());
 J patch={{"schema","rinkfit.joint_packet.v1"},{"dense_parent_packet",parent},{"row_count",3},{"dense_parent_append",{{"groups",J::array({{{"id","g1"}}})}}},{"native_material_identity_revision",{{"file","new"},{"sha256",std::string(64,'b')}}}};auto child=write("child.json",patch);J consumed=J::array();auto merged=extend_joint_dense_packet_document_v1(child.at("file").get<std::string>(),parent.at("file").get<std::string>(),parent.at("sha256"),doc,authorize,read,&consumed);if(merged.at("groups").size()!=2||merged.at("row_count")!=3||merged.at("resolved_native_identity_revision_chain").size()!=2||consumed.size()!=1)throw std::runtime_error("append/chain semantics differ");
 int failures=0;auto reject=[&](const std::string&name,J bad){const auto r=write(name+".json",bad);bool rejected=false;try{extend_joint_dense_packet_document_v1(r.at("file").get<std::string>(),parent.at("file").get<std::string>(),parent.at("sha256"),doc,authorize,read);}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("accepted "+name);++failures;};
 auto bad=patch;bad["source_row_ids"]=J::array({"override"});reject("immutable_ID_override",bad);bad=patch;bad["groups"]=J::array();reject("append_override_conflict",bad);bad=patch;bad["resolved_native_identity_revision_chain"]=J::array();reject("supplied_derived_chain",bad);bad=patch;bad["dense_parent_packet"]["sha256"]=std::string(64,'0');reject("wrong_parent_SHA",bad);bad=patch;bad["dense_parent_append"]["unapproved"]=J::array();reject("unapproved_append_field",bad);bad=patch;bad.erase("dense_parent_packet");reject("different_original_root",bad);
 eventio::atomic_json(argv[2],{{"schema","rinkfit.incremental_dense_document_contract_regression.v1"},{"passed",true},{"strict_rejection_cases",failures},{"append_and_review_history_exact",true},{"only_authenticated_original_descendants_allowed",true},{"solver_started",false}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
